            case "FRETEGRATIS" -> new CupomFreteGratis();
            case "LEVE3PAGUE2" -> new CupomLeve3Pague2(precos);
            default -> throw new IllegalArgumentException("CUPOM_INVALIDO");
        };
    }
}

