    public void exemplo3() {
        RequisicaoCheckoutDTO req = new RequisicaoCheckoutDTO();
        req.itens = new ArrayList<>();
        req.itens.add(new ItemDTO("Fone", new BigDecimal("199.90"), 2, new BigDecimal("0.25")));
