        assertEquals(new BigDecimal("3.49"), resp.ajustePagamento);
        assertEquals(new BigDecimal("371.29"), resp.totalFinal);
        assertEquals(1, resp.parcelas);
        assertEquals(new BigDecimal("371.29"), resp.valorParcela);
    }

